pub use lyric_core::{models,identity};pub mod formats;pub mod crypto;pub mod local;pub mod resolution;pub mod sync;pub mod providers;pub mod http;mod storage;mod io;mod resolver;
use serde_json::{json,Value};use lyric_core::{models::*,cache::Cache};use std::{collections::BTreeMap,sync::{Arc,Mutex,OnceLock,mpsc,atomic::{AtomicU64,AtomicBool,Ordering}},path::PathBuf,time::Duration};
struct Job{cancel:Arc<AtomicBool>,rx:mpsc::Receiver<Lookup>}
fn dispatch(v:Value)->Result<Value,String>{static NEXT:AtomicU64=AtomicU64::new(1);static JOBS:OnceLock<Mutex<BTreeMap<u64,Job>>>=OnceLock::new();static TIMELINES:OnceLock<Mutex<BTreeMap<u64,sync::Timeline>>>=OnceLock::new();let a=&v["args"];let method=v["method"].as_str().ok_or("method")?;
match method{
"provider.search"=>{let provider=a["provider"].as_str().ok_or("provider")?;let ctx=http::RequestContext::new(Duration::from_millis(a["timeoutMs"].as_u64().unwrap_or(5000).min(10000)));let source=providers::OnlineSource::new(provider,ctx);let track=serde_json::from_value(a["track"].clone()).map_err(|e|e.to_string())?;return Ok(json!(resolution::Source::search(&source,&track)?));},
"search.start"=>{let id=NEXT.fetch_add(1,Ordering::Relaxed);let data=PathBuf::from(a["data"].as_str().ok_or("data")?);let logs=PathBuf::from(a["logs"].as_str().ok_or("logs")?);let r=resolver::Resolver{settings:a["settings"].clone(),raw:Arc::new(Cache::new(data.join("database/dotisle-payload-v3.json"))),final_cache:storage::FinalCache(Arc::new(Cache::new(data.join("database/dotisle-lyrics-v3.json")))),data,logs,closed:AtomicBool::new(false)};let track=serde_json::from_value(a["track"].clone()).map_err(|e|e.to_string())?;let cancel=Arc::new(AtomicBool::new(false));let stop=cancel.clone();let(tx,rx)=mpsc::channel();JOBS.get_or_init(Default::default).lock().map_err(|_|"jobs")?.insert(id,Job{cancel,rx});std::thread::spawn(move||{let _=tx.send(r.resolve(&track,stop));});return Ok(json!(id));},
"search.poll"=>{let id=a["id"].as_u64().ok_or("job")?;let mut jobs=JOBS.get_or_init(Default::default).lock().map_err(|_|"jobs")?;let job=jobs.get(&id).ok_or("job missing")?;match job.rx.try_recv(){Ok(r)=>{let result=json!({"ready":true,"lyrics":r.lyrics,"status":match r.status{LookupStatus::Found=>"found",LookupStatus::Missing=>"missing",LookupStatus::TransientFailure=>"transient"}});jobs.remove(&id);return Ok(result);},Err(mpsc::TryRecvError::Empty)=>return Ok(json!({"ready":false})),Err(_)=>{jobs.remove(&id);return Err("lyric worker disconnected".into());}}},
"search.cancel"=>{if let Some(job)=JOBS.get_or_init(Default::default).lock().map_err(|_|"jobs")?.remove(&a["id"].as_u64().ok_or("job")?){job.cancel.store(true,Ordering::Release);}return Ok(Value::Null);},_=>{}}
let mut timelines=TIMELINES.get_or_init(Default::default).lock().map_err(|_|"timelines")?;
if method=="timeline.new"{let id=NEXT.fetch_add(1,Ordering::Relaxed);timelines.insert(id,sync::Timeline::new());return Ok(json!({"handle":id}));}
let id=a["handle"].as_u64().ok_or("timeline handle")?;if method=="timeline.drop"{timelines.remove(&id);return Ok(Value::Null);}
let t=timelines.get_mut(&id).ok_or("timeline missing")?;match method{
"timeline.begin"=>Ok(json!(t.begin_track(&serde_json::from_value(a["track"].clone()).map_err(|e|e.to_string())?))),
"timeline.complete"=>{let selection:Option<Selection>=serde_json::from_value(a["selection"].clone()).map_err(|e|e.to_string())?;t.complete_search(&serde_json::from_value(a["track"].clone()).map_err(|e|e.to_string())?,selection.as_ref());Ok(Value::Null)},
"timeline.frame"=>{let mut playback=Playback::idle();playback.track=serde_json::from_value(a["track"].clone()).map_err(|e|e.to_string())?;playback.position=Duration::from_millis(a["positionMs"].as_u64().unwrap_or(0));let frame=t.get_display_frame(&playback);let previous=if frame.current_line_index>0{t.current_document().and_then(|d|d.lines.get(frame.current_line_index as usize-1)).map(|l|l.text.as_str()).unwrap_or("")}else{""};Ok(json!({"frame":frame,"previous":previous,"source":t.current_lyric_source_app()}))},_=>Err("unknown lyrics method".into())}
}
dotisle_module_api::export_service!("lyrics",dispatch);
